            ui.add_space(70.0);
            ui.label(RichText::new("Cutline needs FFmpeg").size(23.0).strong());
            ui.add_space(4.0);
            ui.label(RichText::new("FFmpeg is the free program that does the actual editing. It's not on this computer yet.").color(MUTED));
            ui.add_space(14.0);
            let hint = if cfg!(target_os = "macos") {
                "On a Mac: install Homebrew, then run  brew install ffmpeg"
            } else if cfg!(windows) {
                "On Windows: open a terminal and run  winget install ffmpeg"
            } else {
                "On Linux: run  sudo apt install ffmpeg  (or use your package manager)"
            };
            ui.label(RichText::new(hint).monospace().color(TEXT));
            ui.add_space(18.0);
            ui.hyperlink_to("Download FFmpeg", "https://ffmpeg.org/download.html");
            ui.add_space(18.0);
            ui.horizontal(|ui| {
                let total = 296.0;
                ui.add_space((ui.available_width() - total).max(0.0) / 2.0);
                if soft_button(ui, "Check again").clicked() {
                    self.find_tools();
                }
                if soft_button(ui, "I installed it somewhere else...").clicked() {
                    self.pick_ffmpeg();
                }
            });
        });
    }
}
