use eframe::egui::{self, Color32, ColorImage, Margin, TextureHandle, TextureOptions};
use std::ffi::OsString;
use std::path::{Path, PathBuf};
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::Arc;
