            part_limits: vec!["20".to_string()],
            same_limit: true,
            base_name: "edited_video".to_string(),
            name_edited: false,
            out_dir: read("out_dir").map(PathBuf::from),
            playhead: 0.0,
            playing: false,
            preview: None,
            preview_texture: None,
            preview_dirty: false,
            last_shape: None,
            job: None,
            part_states: Vec::new(),
            export_result: None,
            export_started: None,
            console: Vec::new(),
            show_console: read("show_console").as_deref() == Some("1"),
            toasts: Vec::new(),
            screenshot: screenshot.map(|path| ScreenshotJob { path, frames: 0, requested: false, saved, saved_tx }),
        };
        app.find_tools_with(&cc.egui_ctx);
        app.add_files(files);
        app
    }

    pub fn find_tools(&mut self) {
        if let Some(ctx) = self.preview_ctx.clone() {
            self.find_tools_with(&ctx);
        }
    }
}
