//! Colours, spacing and small shared widgets.

use eframe::egui::{self, Color32, CornerRadius, FontFamily, FontId, Margin, Rect, RichText, Sense, Stroke, StrokeKind, TextStyle, Theme, Ui, Vec2};

pub const BG: Color32 = Color32::from_rgb(15, 17, 21);
pub const PANEL: Color32 = Color32::from_rgb(22, 25, 31);
pub const CARD: Color32 = Color32::from_rgb(29, 33, 41);
pub const RAISED: Color32 = Color32::from_rgb(38, 43, 53);
pub const LINE: Color32 = Color32::from_rgb(46, 52, 64);
pub const TEXT: Color32 = Color32::from_rgb(233, 236, 241);
pub const MUTED: Color32 = Color32::from_rgb(142, 150, 165);
pub const FAINT: Color32 = Color32::from_rgb(92, 100, 115);
pub const ACCENT: Color32 = Color32::from_rgb(110, 123, 255);
pub const ACCENT_HOVER: Color32 = Color32::from_rgb(132, 144, 255);
pub const GOOD: Color32 = Color32::from_rgb(62, 214, 176);
pub const WARN: Color32 = Color32::from_rgb(245, 184, 75);
pub const BAD: Color32 = Color32::from_rgb(240, 96, 112);

const PART_COLORS: [Color32; 6] = [
    Color32::from_rgb(110, 123, 255),
    Color32::from_rgb(62, 214, 176),
    Color32::from_rgb(245, 184, 75),
    Color32::from_rgb(240, 111, 168),
    Color32::from_rgb(79, 184, 245),
    Color32::from_rgb(165, 214, 78),
];

const CLIP_COLORS: [Color32; 6] = [
    Color32::from_rgb(52, 62, 110),
    Color32::from_rgb(40, 88, 78),
    Color32::from_rgb(100, 78, 44),
    Color32::from_rgb(98, 54, 80),
    Color32::from_rgb(42, 84, 108),
    Color32::from_rgb(72, 90, 50),
];

pub fn part_color(index: usize) -> Color32 {
    PART_COLORS[index % PART_COLORS.len()]
}

pub fn clip_color(id: u64) -> Color32 {
    CLIP_COLORS[id as usize % CLIP_COLORS.len()]
}

pub fn apply(ctx: &egui::Context) {
    ctx.set_theme(Theme::Dark);
    ctx.style_mut_of(Theme::Dark, |style| {
        style.text_styles = [
            (TextStyle::Small, FontId::new(11.0, FontFamily::Proportional)),
            (TextStyle::Body, FontId::new(13.5, FontFamily::Proportional)),
            (TextStyle::Button, FontId::new(13.5, FontFamily::Proportional)),
            (TextStyle::Heading, FontId::new(19.0, FontFamily::Proportional)),
            (TextStyle::Monospace, FontId::new(12.0, FontFamily::Monospace)),
        ]
        .into();
        let spacing = &mut style.spacing;
        spacing.item_spacing = Vec2::new(8.0, 8.0);
        spacing.button_padding = Vec2::new(10.0, 6.0);
        spacing.interact_size = Vec2::new(36.0, 28.0);
        spacing.combo_height = 320.0;

        let visuals = &mut style.visuals;
        visuals.dark_mode = true;
        visuals.panel_fill = PANEL;
        visuals.window_fill = CARD;
        visuals.extreme_bg_color = BG;
        visuals.faint_bg_color = CARD;
        visuals.override_text_color = Some(TEXT);
        visuals.selection.bg_fill = ACCENT.linear_multiply(0.45);
        visuals.selection.stroke = Stroke::new(1.0, ACCENT_HOVER);
        visuals.hyperlink_color = ACCENT_HOVER;
        visuals.window_stroke = Stroke::new(1.0, LINE);
        let radius = CornerRadius::same(7);
        for (widget, fill, border) in [
            (&mut visuals.widgets.noninteractive, CARD, LINE),
            (&mut visuals.widgets.inactive, RAISED, LINE),
            (&mut visuals.widgets.hovered, Color32::from_rgb(50, 56, 69), Color32::from_rgb(70, 78, 94)),
            (&mut visuals.widgets.active, Color32::from_rgb(58, 65, 80), ACCENT),
            (&mut visuals.widgets.open, Color32::from_rgb(50, 56, 69), ACCENT),
        ] {
            widget.bg_fill = fill;
            widget.weak_bg_fill = fill;
            widget.bg_stroke = Stroke::new(1.0, border);
            widget.corner_radius = radius;
            widget.fg_stroke = Stroke::new(1.2, TEXT);
            widget.expansion = 0.0;
        }
        visuals.widgets.noninteractive.fg_stroke = Stroke::new(1.0, TEXT);
    });
}

/// A small heading over a group of controls.
pub fn section_label(ui: &mut Ui, text: &str) {
    ui.label(RichText::new(text).size(11.5).strong().color(MUTED));
}

/// A rounded group of controls.
pub fn card<R>(ui: &mut Ui, add: impl FnOnce(&mut Ui) -> R) -> R {
    egui::Frame::new()
        .fill(CARD)
        .stroke(Stroke::new(1.0, LINE))
        .corner_radius(CornerRadius::same(10))
        .inner_margin(Margin::same(12))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            add(ui)
        })
        .inner
}

/// An on/off switch. Returns true when flipped.
pub fn toggle(ui: &mut Ui, on: &mut bool) -> bool {
    let size = Vec2::new(36.0, 20.0);
    let (rect, mut response) = ui.allocate_exact_size(size, Sense::click());
    if response.clicked() {
        *on = !*on;
        response.mark_changed();
    }
    let t = ui.ctx().animate_bool_responsive(response.id, *on);
    let fill = Color32::from_rgb(
        egui::lerp(60.0..=110.0, t) as u8,
        egui::lerp(66.0..=123.0, t) as u8,
        egui::lerp(80.0..=255.0, t) as u8,
    );
    let radius = rect.height() / 2.0;
    let painter = ui.painter();
    painter.rect_filled(rect, radius, fill);
    let x = egui::lerp((rect.left() + radius)..=(rect.right() - radius), t);
    painter.circle_filled(egui::pos2(x, rect.center().y), radius - 3.0, Color32::WHITE);
    response.changed()
}

/// A big filled button.
pub fn primary_button(ui: &mut Ui, text: &str, size: Vec2, enabled: bool) -> egui::Response {
    let (rect, response) = ui.allocate_exact_size(size, if enabled { Sense::click() } else { Sense::hover() });
    let fill = match (enabled, response.hovered()) {
        (false, _) => RAISED,
        (true, true) => ACCENT_HOVER,
        (true, false) => ACCENT,
    };
    let color = if enabled { Color32::WHITE } else { FAINT };
    let painter = ui.painter();
    painter.rect_filled(rect, CornerRadius::same(9), fill);
    painter.text(rect.center(), egui::Align2::CENTER_CENTER, text, FontId::new(15.0, FontFamily::Proportional), color);
    if enabled {
        response.on_hover_cursor(egui::CursorIcon::PointingHand)
    } else {
        response
    }
}

/// A flat text button that lights up when hovered.
pub fn soft_button(ui: &mut Ui, text: &str) -> egui::Response {
    ui.add(egui::Button::new(RichText::new(text).size(12.5)).fill(RAISED).stroke(Stroke::new(1.0, LINE)))
}

/// A square button with a drawn icon.
pub fn icon_button(ui: &mut Ui, size: f32, enabled: bool, draw: impl FnOnce(&egui::Painter, Rect, Color32)) -> egui::Response {
    let (rect, response) = ui.allocate_exact_size(Vec2::splat(size), if enabled { Sense::click() } else { Sense::hover() });
    let color = if !enabled {
        FAINT
    } else if response.hovered() {
        TEXT
    } else {
        Color32::from_rgb(188, 194, 206)
    };
    let painter = ui.painter();
    if enabled && response.hovered() {
        painter.rect_filled(rect, CornerRadius::same(6), RAISED);
    }
    draw(painter, rect, color);
    response
}

pub fn triangle(painter: &egui::Painter, center: egui::Pos2, half: f32, direction: f32, color: Color32) {
    let points = vec![
        center + Vec2::new(-half * direction, -half),
        center + Vec2::new(half * direction, 0.0),
        center + Vec2::new(-half * direction, half),
    ];
    painter.add(egui::Shape::convex_polygon(points, color, Stroke::NONE));
}

pub fn draw_play(painter: &egui::Painter, rect: Rect, color: Color32) {
    triangle(painter, rect.center() + Vec2::new(1.5, 0.0), rect.width() * 0.24, 1.0, color);
}

pub fn draw_pause(painter: &egui::Painter, rect: Rect, color: Color32) {
    let center = rect.center();
    let (half_width, half_height) = (rect.width() * 0.07, rect.height() * 0.22);
    for side in [-1.0, 1.0] {
        let bar = Rect::from_center_size(center + Vec2::new(side * rect.width() * 0.13, 0.0), Vec2::new(half_width * 2.0, half_height * 2.0));
        painter.rect_filled(bar, CornerRadius::same(1), color);
    }
}

pub fn draw_skip(painter: &egui::Painter, rect: Rect, color: Color32, direction: f32) {
    let center = rect.center();
    let half = rect.width() * 0.19;
    triangle(painter, center + Vec2::new(-1.5 * direction, 0.0), half, direction, color);
    let x = center.x + (half + 0.5) * direction;
    painter.line_segment(
        [egui::pos2(x, center.y - half), egui::pos2(x, center.y + half)],
        Stroke::new(2.0, color),
    );
}

pub fn draw_close(painter: &egui::Painter, rect: Rect, color: Color32) {
    let center = rect.center();
    let half = rect.width() * 0.2;
    let stroke = Stroke::new(1.6, color);
    painter.line_segment([center + Vec2::splat(-half), center + Vec2::splat(half)], stroke);
    painter.line_segment([center + Vec2::new(-half, half), center + Vec2::new(half, -half)], stroke);
}

pub fn draw_chevron(painter: &egui::Painter, rect: Rect, color: Color32, up: bool) {
    let center = rect.center();
    let half = rect.width() * 0.2;
    let lift = if up { -half * 0.5 } else { half * 0.5 };
    let tip = center + Vec2::new(0.0, -lift * 2.0);
    let stroke = Stroke::new(1.8, color);
    painter.line_segment([center + Vec2::new(-half, lift), tip], stroke);
    painter.line_segment([tip, center + Vec2::new(half, lift)], stroke);
}

/// A dashed outline.
pub fn dashed_rect(painter: &egui::Painter, rect: Rect, stroke: Stroke) {
    let corners = [rect.left_top(), rect.right_top(), rect.right_bottom(), rect.left_bottom(), rect.left_top()];
    for pair in corners.windows(2) {
        painter.add(egui::Shape::dashed_line(&[pair[0], pair[1]], stroke, 10.0, 7.0));
    }
}

/// The outline around a selected thing.
pub fn outline(painter: &egui::Painter, rect: Rect, radius: u8, stroke: Stroke) {
    painter.rect_stroke(rect, CornerRadius::same(radius), stroke, StrokeKind::Inside);
}

//! The "View console" panel: every FFmpeg command and its output as it runs.

use super::theme::*;
use crate::app::App;
use cutline::log::LogKind;
use eframe::egui::{self, RichText, Ui};

impl App {
    pub fn console_panel(&mut self, ui: &mut Ui) {
        ui.horizontal(|ui| {
            ui.label(RichText::new("Console").strong());
            ui.label(RichText::new("the FFmpeg commands, as they run").size(12.0).color(FAINT));
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                if soft_button(ui, "Clear").clicked() {
                    self.console.clear();
                }
                if soft_button(ui, "Copy all").clicked() {
                    let text: Vec<&str> = self.console.iter().map(|line| line.text.as_str()).collect();
                    ui.ctx().copy_text(text.join("\n"));
                    self.toast("Copied the console");
                }
            });
        });
        egui::Frame::new().fill(BG).corner_radius(8.0).inner_margin(10.0).show(ui, |ui| {
            ui.set_min_size(ui.available_size());
            egui::ScrollArea::both().auto_shrink(false).stick_to_bottom(true).show(ui, |ui| {
                ui.style_mut().spacing.item_spacing.y = 3.0;
                if self.console.is_empty() {
                    ui.label(RichText::new("Commands appear here as they run.").monospace().color(FAINT));
                }
                for line in &self.console {
                    let text = RichText::new(line.text.as_str()).monospace();
                    let styled = match line.kind {
                        LogKind::Command => RichText::new(format!("$ {}", line.text)).monospace().color(ACCENT_HOVER).strong(),
                        LogKind::Info => text.color(TEXT),
                        LogKind::Output => text.color(MUTED),
                        LogKind::Warning => text.color(WARN),
                        LogKind::Error => text.color(BAD),
                        LogKind::Success | LogKind::Live => text.color(GOOD),
                    };
                    ui.add(egui::Label::new(styled).wrap_mode(egui::TextWrapMode::Extend).selectable(true));
                }
            });
        });
    }
}

//! The list of videos on the left.

use super::theme::*;
use crate::app::App;
use cutline::media::{clock, human_bytes};
use eframe::egui::{self, pos2, vec2, Align2, Color32, CornerRadius, FontFamily, FontId, Rect, RichText, Sense, Stroke, Ui};

const ROW_HEIGHT: f32 = 64.0;

enum RowAction {
    Select(usize),
    Move(usize, usize),
    Remove(usize),
}

impl App {
    pub fn media_panel(&mut self, ui: &mut Ui) {
        ui.horizontal(|ui| {
            ui.label(RichText::new("Videos").size(15.0).strong());
            if !self.clips.is_empty() {
                ui.label(RichText::new(self.clips.len().to_string()).size(13.0).color(FAINT));
            }
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                let enabled = !self.exporting();
                if ui.add_enabled(enabled, egui::Button::new(RichText::new("+ Add").size(12.5))).on_hover_text("Choose videos to add").clicked() {
                    self.add_with_dialog();
                }
                if self.manual_order
                    && ui
                        .add_enabled(enabled, egui::Button::new(RichText::new("A-Z").size(12.5)))
                        .on_hover_text("Put back in alphabetical order")
                        .clicked()
                {
                    self.sort_alphabetically();
                }
            });
        });

        if self.clips.is_empty() && self.probing == 0 {
            ui.add_space(4.0);
            ui.label(RichText::new("Drop videos anywhere in the window. They line up back to back, in alphabetical order.").size(12.5).color(MUTED));
            return;
        }

        let mut action = None;
        egui::ScrollArea::vertical().auto_shrink(false).show(ui, |ui| {
            ui.style_mut().spacing.item_spacing.y = 4.0;
            let width = ui.available_width();
            let mut rows: Vec<Rect> = Vec::with_capacity(self.clips.len());
            for index in 0..self.clips.len() {
                let (rect, response) = ui.allocate_exact_size(vec2(width, ROW_HEIGHT), Sense::click_and_drag());
                rows.push(rect);
                if response.clicked() {
                    action = Some(RowAction::Select(index));
                }
                if response.drag_started() && !self.exporting() {
                    self.list_drag = Some(index);
                }
                self.draw_row(ui, index, rect, response.hovered(), &mut action);
                if response.hovered() {
                    ui.ctx().set_cursor_icon(egui::CursorIcon::Grab);
                }
            }

            if self.probing > 0 {
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    ui.spinner();
                    let label = if self.probing == 1 { "Reading a video...".to_string() } else { format!("Reading {} videos...", self.probing) };
                    ui.label(RichText::new(label).size(12.5).color(MUTED));
                });
            }

            if let Some(from) = self.list_drag {
                let pointer = ui.ctx().pointer_latest_pos().unwrap_or_default();
                let target = rows.iter().position(|row| pointer.y < row.center().y).unwrap_or(rows.len());
                if target != from && target != from + 1 && !rows.is_empty() {
                    let y = if target < rows.len() { rows[target].top() - 2.0 } else { rows[rows.len() - 1].bottom() + 2.0 };
                    ui.painter().line_segment([pos2(rows[0].left(), y), pos2(rows[0].right(), y)], Stroke::new(2.5, ACCENT_HOVER));
                }
                if ui.input(|input| input.pointer.any_released()) {
                    self.list_drag = None;
                    if target != from && target != from + 1 {
                        action = Some(RowAction::Move(from, target));
                    }
                }
            }
        });

        match action {
            Some(RowAction::Select(index)) => self.select_clip(index),
            Some(RowAction::Move(from, target)) => self.move_clip(from, target),
            Some(RowAction::Remove(index)) => self.remove_clip(index),
            None => {}
        }
    }

    fn draw_row(&self, ui: &mut Ui, index: usize, rect: Rect, hovered: bool, action: &mut Option<RowAction>) {
        let clip = &self.clips[index];
        let selected = self.selected == Some(clip.id);
        let dragged = self.list_drag == Some(index);
        let fill = if selected {
            Color32::from_rgb(40, 46, 66)
        } else if hovered {
            RAISED
        } else {
            CARD
        };
        let painter = ui.painter().clone();
        painter.rect_filled(rect, CornerRadius::same(9), fill);
        if selected {
            outline(&painter, rect, 9, Stroke::new(1.2, ACCENT));
        }

        let thumb = Rect::from_min_size(rect.min + vec2(9.0, 9.0), vec2(82.0, 46.0));
        match clip.thumbs.get(clip.thumbs.len() / 2).and_then(|t| t.as_ref()).or(clip.thumbs.iter().flatten().next()) {
            Some(texture) => {
                let tint = if dragged { Color32::from_gray(90) } else { Color32::WHITE };
                egui::Image::new(texture).corner_radius(CornerRadius::same(5)).tint(tint).paint_at(ui, thumb);
            }
            None => {
                painter.rect_filled(thumb, CornerRadius::same(5), clip_color(clip.id));
            }
        }
        let badge = Rect::from_min_size(thumb.min + vec2(3.0, 3.0), vec2(18.0, 16.0));
        painter.rect_filled(badge, CornerRadius::same(4), Color32::from_black_alpha(170));
        painter.text(badge.center(), Align2::CENTER_CENTER, (index + 1).to_string(), FontId::new(10.5, FontFamily::Proportional), TEXT);

        let text_left = thumb.right() + 10.0;
        let text_right = rect.right() - if hovered { 78.0 } else { 10.0 };
        let name_clip = Rect::from_min_max(pos2(text_left, rect.top()), pos2(text_right, rect.bottom()));
        let name_painter = painter.with_clip_rect(name_clip.intersect(painter.clip_rect()));
        let color = if dragged { FAINT } else { TEXT };
        name_painter.text(pos2(text_left, rect.top() + 21.0), Align2::LEFT_CENTER, &clip.info.name, FontId::new(13.5, FontFamily::Proportional), color);
        let details = format!("{} x {} · {} · {}", clip.info.width, clip.info.height, clock(clip.info.duration), human_bytes(clip.info.bytes as f64));
        name_painter.text(pos2(text_left, rect.top() + 42.0), Align2::LEFT_CENTER, details, FontId::new(11.5, FontFamily::Proportional), MUTED);

        if hovered && !self.exporting() {
            let mut buttons = ui.new_child(
                egui::UiBuilder::new()
                    .max_rect(Rect::from_min_size(pos2(rect.right() - 76.0, rect.center().y - 12.0), vec2(72.0, 24.0)))
                    .layout(egui::Layout::left_to_right(egui::Align::Center)),
            );
            buttons.style_mut().spacing.item_spacing.x = 0.0;
            let up = icon_button(&mut buttons, 24.0, index > 0, |p, r, c| draw_chevron(p, r, c, true)).on_hover_text("Earlier");
            if up.clicked() {
                *action = Some(RowAction::Move(index, index - 1));
            }
            let down = icon_button(&mut buttons, 24.0, index + 1 < self.clips.len(), |p, r, c| draw_chevron(p, r, c, false)).on_hover_text("Later");
            if down.clicked() {
                *action = Some(RowAction::Move(index, index + 2));
            }
            if icon_button(&mut buttons, 24.0, true, draw_close).on_hover_text("Remove").clicked() {
                *action = Some(RowAction::Remove(index));
            }
        }
    }
}

//! The picture in the middle and its play controls.

use super::theme::*;
use crate::app::App;
use cutline::media::{clock, fine_clock};
use eframe::egui::{self, pos2, vec2, Align2, Color32, CornerRadius, FontFamily, FontId, Rect, RichText, Stroke, Ui};

impl App {
    pub fn preview_panel(&mut self, ui: &mut Ui) {
        if self.tools.is_none() {
            self.missing_ffmpeg(ui);
            return;
        }
        if self.clips.is_empty() {
            self.empty_state(ui);
            return;
        }

        let transport_height = 44.0;
        let area = ui.available_rect_before_wrap();
        let picture_area = Rect::from_min_max(area.min, pos2(area.right(), area.bottom() - transport_height));
        let painter = ui.painter().clone();
        painter.rect_filled(picture_area, CornerRadius::same(10), BG);

        let (width, height) = self.output_dims();
        let aspect = width as f32 / height as f32;
        let mut fit_width = picture_area.width() - 16.0;
        let mut fit_height = fit_width / aspect;
        if fit_height > picture_area.height() - 16.0 {
            fit_height = picture_area.height() - 16.0;
            fit_width = fit_height * aspect;
        }
        let fitted = Rect::from_center_size(picture_area.center(), vec2(fit_width, fit_height));
        painter.rect_filled(fitted, CornerRadius::same(3), Color32::BLACK);
        if let Some(texture) = &self.preview_texture {
            egui::Image::new(texture).paint_at(ui, fitted);
        } else {
            painter.text(fitted.center(), Align2::CENTER_CENTER, "Loading picture...", FontId::new(14.0, FontFamily::Proportional), FAINT);
        }

        let transport = Rect::from_min_max(pos2(area.left(), picture_area.bottom() + 8.0), area.max);
        let mut bar = ui.new_child(egui::UiBuilder::new().max_rect(transport).layout(egui::Layout::left_to_right(egui::Align::Center)));
        bar.style_mut().spacing.item_spacing.x = 4.0;
        if icon_button(&mut bar, 32.0, true, |p, r, c| draw_skip(p, r, c, -1.0)).on_hover_text("Previous video").clicked() {
            self.skip_clip(false);
        }
        let playing = self.playing;
        let play = icon_button(&mut bar, 36.0, true, |p, r, c| if playing { draw_pause(p, r, c) } else { draw_play(p, r, c) })
            .on_hover_text("Play or pause (Space). The preview has no sound.");
        if play.clicked() {
            self.toggle_play();
        }
        if icon_button(&mut bar, 32.0, true, |p, r, c| draw_skip(p, r, c, 1.0)).on_hover_text("Next video").clicked() {
            self.skip_clip(true);
        }
        bar.add_space(10.0);
        bar.label(RichText::new(fine_clock(self.playhead)).monospace().size(14.0));
        bar.label(RichText::new(format!("/ {}", clock(self.total_duration()))).monospace().size(13.0).color(FAINT));
        bar.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
            ui.label(RichText::new(format!("Output {width} x {height}")).size(12.5).color(FAINT));
        });
    }

    fn empty_state(&mut self, ui: &mut Ui) {
        let area = ui.available_rect_before_wrap();
        let painter = ui.painter().clone();
        let zone = area.shrink(14.0);
        painter.rect_filled(zone, CornerRadius::same(16), Color32::from_rgb(19, 21, 27));
        dashed_rect(&painter, zone.shrink(1.0), Stroke::new(1.5, LINE));
        let center = zone.center() - vec2(0.0, 28.0);
        let strip = Rect::from_center_size(center - vec2(0.0, 34.0), vec2(120.0, 76.0));
        painter.rect_filled(strip, CornerRadius::same(10), RAISED);
        for row in [strip.top() + 6.0, strip.bottom() - 15.0] {
            for hole in 0..6 {
                let x = strip.left() + 11.0 + hole as f32 * 18.5;
                painter.rect_filled(Rect::from_min_size(pos2(x, row), vec2(10.0, 9.0)), CornerRadius::same(2), BG);
            }
        }
        triangle(&painter, strip.center() + vec2(2.0, 0.0), 13.0, 1.0, ACCENT_HOVER);
        painter.text(center + vec2(0.0, 28.0), Align2::CENTER_CENTER, "Drop your videos here", FontId::new(23.0, FontFamily::Proportional), TEXT);
        painter.text(
            center + vec2(0.0, 58.0),
            Align2::CENTER_CENTER,
            "They join back to back in alphabetical order. You can rearrange them after.",
            FontId::new(14.0, FontFamily::Proportional),
            MUTED,
        );

        let button = Rect::from_center_size(center + vec2(0.0, 106.0), vec2(190.0, 44.0));
        let mut child = ui.new_child(egui::UiBuilder::new().max_rect(button));
        if primary_button(&mut child, "Choose videos", button.size(), true).clicked() {
            self.add_with_dialog();
        }
    }

    fn missing_ffmpeg(&mut self, ui: &mut Ui) {
        ui.vertical_centered(|ui| {
            ui.add_space(70.0);
            ui.label(RichText::new("Cutline needs FFmpeg").size(23.0).strong());
            ui.add_space(4.0);
            ui.label(RichText::new("FFmpeg is the free program that does the actual editing. It isn't on this computer yet.").color(MUTED));
            ui.add_space(14.0);
            let hint = if cfg!(target_os = "macos") {
                "On a Mac, with Homebrew:  brew install ffmpeg"
            } else if cfg!(windows) {
                "On Windows, in a terminal:  winget install ffmpeg"
            } else {
                "On Linux, use your package manager to install: ffmpeg"
            };
            ui.label(RichText::new(hint).monospace().color(TEXT));
            ui.add_space(18.0);
            ui.hyperlink_to("Download FFmpeg", "https://ffmpeg.org/download.html");
            ui.add_space(18.0);
            ui.horizontal(|ui| {
                let total = 296.0;
                ui.add_space((ui.available_width() - total).max(0.0) / 2.0);
                if soft_button(ui, "Check again").clicked() {
                    self.find_tools();
                }
                if soft_button(ui, "It's installed somewhere else...").clicked() {
                    self.pick_ffmpeg();
                }
            });
        });
    }
}

//! The strip along the bottom: every clip end to end, and where the result videos will be cut.

use super::theme::*;
use crate::app::App;
use cutline::media::{clock, THUMB_HEIGHT, THUMB_WIDTH};
use cutline::plan::Plan;
use eframe::egui::{self, pos2, vec2, Align2, Color32, CornerRadius, FontFamily, FontId, Id, Rect, Sense, Stroke, Ui};

const STEPS: [f64; 14] = [1.0, 2.0, 5.0, 10.0, 15.0, 30.0, 60.0, 120.0, 300.0, 600.0, 900.0, 1800.0, 3600.0, 7200.0];

impl App {
    pub fn timeline_panel(&mut self, ui: &mut Ui, plan: Option<&Plan>) {
        let area = ui.available_rect_before_wrap();
        let ruler = Rect::from_min_size(area.min, vec2(area.width(), 22.0));
        let bands = Rect::from_min_size(pos2(area.left(), ruler.bottom() + 2.0), vec2(area.width(), 20.0));
        let track = Rect::from_min_max(pos2(area.left(), bands.bottom() + 5.0), area.max);
        ui.allocate_rect(area, Sense::hover());
        let painter = ui.painter_at(area.expand(1.0));
        let total = self.total_duration();

        if self.clips.is_empty() {
            painter.rect_filled(track, CornerRadius::same(8), BG);
            dashed_rect(&painter, track.shrink(1.0), Stroke::new(1.0, LINE));
            painter.text(track.center(), Align2::CENTER_CENTER, "Your timeline will appear here", FontId::new(13.0, FontFamily::Proportional), FAINT);
            return;
        }

        let x_at = |time: f64| area.left() + (time / total) as f32 * area.width();

        // Ruler: click or drag to move the playhead.
        let ruler_hit = ui.interact(ruler.union(bands), Id::new("ruler"), Sense::click_and_drag());
        if ruler_hit.is_pointer_button_down_on() {
            if let Some(pointer) = ruler_hit.interact_pointer_pos() {
                self.seek(((pointer.x - area.left()) / area.width()) as f64 * total);
            }
        }
        if ruler_hit.hovered() {
            ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
        }
        let step = STEPS.iter().copied().find(|step| (step / total) as f32 * area.width() >= 72.0).unwrap_or(14400.0);
        let mut tick = 0.0;
        while tick < total {
            let x = x_at(tick);
            painter.line_segment([pos2(x, ruler.bottom() - 7.0), pos2(x, ruler.bottom())], Stroke::new(1.0, FAINT));
            let minor = x_at(tick + step / 2.0);
            painter.line_segment([pos2(minor, ruler.bottom() - 4.0), pos2(minor, ruler.bottom())], Stroke::new(1.0, LINE));
            painter.text(pos2(x + 4.0, ruler.top() + 3.0), Align2::LEFT_TOP, clock(tick), FontId::new(10.5, FontFamily::Monospace), FAINT);
            tick += step;
        }

        // The result videos.
        if let Some(plan) = plan {
            for part in &plan.parts {
                let rect = Rect::from_min_max(
                    pos2(x_at(part.start) + 1.0, bands.top()),
                    pos2(x_at(part.start + part.duration) - 1.0, bands.bottom()),
                );
                let color = part_color(part.index);
                painter.rect_filled(rect, CornerRadius::same(4), color.linear_multiply(0.28));
                let label = if plan.parts.len() == 1 {
                    format!("Final video · {}", clock(part.duration))
                } else {
                    format!("Part {} · {}", part.index + 1, clock(part.duration))
                };
                painter.with_clip_rect(rect.intersect(painter.clip_rect())).text(
                    rect.center(),
                    Align2::CENTER_CENTER,
                    label,
                    FontId::new(11.5, FontFamily::Proportional),
                    color,
                );
            }
        }

        // The clips.
        painter.rect_filled(track, CornerRadius::same(8), BG);
        let mut blocks: Vec<Rect> = Vec::with_capacity(self.clips.len());
        let mut clip_start = 0.0;
        for clip in &self.clips {
            let left = x_at(clip_start);
            clip_start += clip.info.duration;
            let right = x_at(clip_start);
            blocks.push(Rect::from_min_max(pos2(left, track.top()), pos2(right, track.bottom())));
        }
        let mut clicked = None;
        for (index, block) in blocks.iter().enumerate() {
            let response = ui.interact(*block, Id::new(("clip block", self.clips[index].id)), Sense::click_and_drag());
            if response.clicked() {
                clicked = Some((index, response.interact_pointer_pos()));
            }
            if response.drag_started() && !self.exporting() {
                self.timeline_drag = Some(index);
            }
            if response.hovered() {
                ui.ctx().set_cursor_icon(egui::CursorIcon::Grab);
            }
            self.draw_block(ui, &painter, index, *block);
        }

        if let Some(plan) = plan {
            for part in plan.parts.iter().skip(1) {
                let x = x_at(part.start);
                painter.line_segment([pos2(x, bands.bottom()), pos2(x, track.bottom())], Stroke::new(2.0, part_color(part.index)));
            }
        }

        if let Some(from) = self.timeline_drag {
            ui.ctx().set_cursor_icon(egui::CursorIcon::Grabbing);
            let pointer = ui.ctx().pointer_latest_pos().unwrap_or_default();
            let target = blocks.iter().position(|block| pointer.x < block.center().x).unwrap_or(blocks.len());
            if target != from && target != from + 1 {
                let x = if target < blocks.len() { blocks[target].left() } else { blocks[blocks.len() - 1].right() };
                painter.line_segment([pos2(x, track.top() - 3.0), pos2(x, track.bottom() + 1.0)], Stroke::new(3.0, Color32::WHITE));
            }
            let ghost = Rect::from_center_size(pos2(pointer.x, track.center().y), vec2(blocks[from].width().clamp(70.0, 180.0), track.height() - 8.0));
            painter.rect_filled(ghost, CornerRadius::same(6), ACCENT.linear_multiply(0.45));
            outline(&painter, ghost, 6, Stroke::new(1.5, ACCENT_HOVER));
            if ui.input(|input| input.pointer.any_released()) {
                self.timeline_drag = None;
                if target != from && target != from + 1 {
                    self.move_clip(from, target);
                }
            }
        }

        if let Some((index, pointer)) = clicked {
            self.selected = Some(self.clips[index].id);
            if let Some(pointer) = pointer {
                self.seek(((pointer.x - area.left()) / area.width()) as f64 * total);
            }
        }

        // The playhead, on top of everything.
        let x = x_at(self.playhead.min(total));
        painter.line_segment([pos2(x, ruler.top() + 8.0), pos2(x, track.bottom())], Stroke::new(1.6, Color32::WHITE));
        let cap = vec![
            pos2(x - 6.0, ruler.top()),
            pos2(x + 6.0, ruler.top()),
            pos2(x + 6.0, ruler.top() + 6.0),
            pos2(x, ruler.top() + 13.0),
            pos2(x - 6.0, ruler.top() + 6.0),
        ];
        painter.add(egui::Shape::convex_polygon(cap, Color32::WHITE, Stroke::NONE));
    }

    fn draw_block(&self, ui: &Ui, painter: &egui::Painter, index: usize, block: Rect) {
        let clip = &self.clips[index];
        let inner = block.shrink2(vec2(1.0, 0.0));
        let dimmed = self.timeline_drag == Some(index);
        painter.rect_filled(inner, CornerRadius::same(6), clip_color(clip.id));
        let tile_width = inner.height() * THUMB_WIDTH as f32 / THUMB_HEIGHT as f32;
        let tiles = ((inner.width() / tile_width).ceil() as usize).max(1);
        let textures: Vec<_> = clip.thumbs.iter().flatten().collect();
        if !textures.is_empty() {
            let strip = painter.with_clip_rect(inner.intersect(painter.clip_rect()));
            for tile in 0..tiles {
                let left = inner.left() + tile as f32 * tile_width;
                let slot = (tile * clip.thumbs.len()) / tiles;
                let Some(texture) = clip.thumbs.get(slot).and_then(|t| t.as_ref()).or(textures.first().copied()) else { continue };
                let rect = Rect::from_min_size(pos2(left, inner.top()), vec2(tile_width, inner.height()));
                let tint = if dimmed { Color32::from_gray(70) } else { Color32::from_gray(205) };
                strip.image(texture.id(), rect, Rect::from_min_max(pos2(0.0, 0.0), pos2(1.0, 1.0)), tint);
            }
        }
        let selected = self.selected == Some(clip.id);
        let stroke = if selected { Stroke::new(2.0, ACCENT_HOVER) } else { Stroke::new(1.0, Color32::from_white_alpha(38)) };
        outline(painter, inner, 6, stroke);

        let label_band = Rect::from_min_max(pos2(inner.left(), inner.bottom() - 22.0), inner.max);
        let text_painter = painter.with_clip_rect(inner.shrink(1.0).intersect(painter.clip_rect()));
        text_painter.rect_filled(label_band, CornerRadius::ZERO, Color32::from_black_alpha(150));
        let font = FontId::new(11.5, FontFamily::Proportional);
        text_painter.text(pos2(inner.left() + 7.0, label_band.center().y), Align2::LEFT_CENTER, format!("{}  {}", index + 1, clip.info.name), font.clone(), TEXT);
        let duration = clock(clip.info.duration);
        let duration_width = ui.fonts_mut(|fonts| fonts.layout_no_wrap(duration.clone(), font.clone(), TEXT).size().x);
        if inner.width() > duration_width + 100.0 {
            text_painter.text(pos2(inner.right() - 7.0, label_band.center().y), Align2::RIGHT_CENTER, duration, font, MUTED);
        }
    }
}

//! The settings on the right: format, picture size, how many videos, how big each may be, and Export.

use super::theme::*;
use crate::app::{open_folder, App, PartState, SIZE_PRESETS};
use cutline::media::{clock, human_bytes};
use cutline::plan::{format_available, Fit, FormatChoice, Plan, Quality, FORMATS};
use eframe::egui::{self, vec2, Color32, Margin, RichText, Stroke, Ui};

impl App {
    pub fn output_panel(&mut self, ui: &mut Ui, plan: Option<&Plan>) {
        let exporting = self.exporting();
        egui::Panel::bottom("export footer")
            .frame(egui::Frame::new().inner_margin(Margin::symmetric(0, 10)).fill(PANEL))
            .show_separator_line(false)
            .resizable(false)
            .show_inside(ui, |ui| self.export_footer(ui, plan));
        egui::ScrollArea::vertical().auto_shrink(false).show(ui, |ui| {
            ui.style_mut().spacing.item_spacing.y = 10.0;
            ui.add_enabled_ui(!exporting, |ui| {
                self.format_card(ui);
                self.size_card(ui, plan);
            });
            self.parts_card(ui, plan, exporting);
            ui.add_enabled_ui(!exporting, |ui| self.save_card(ui, plan));
        });
    }

    fn format_card(&mut self, ui: &mut Ui) {
        card(ui, |ui| {
            section_label(ui, "Save as");
            let label = match &self.format {
                FormatChoice::Listed(index) => FORMATS[*index].label.to_string(),
                FormatChoice::Other(_) => "Other format...".to_string(),
            };
            egui::ComboBox::from_id_salt("format").selected_text(label).width(ui.available_width()).show_ui(ui, |ui| {
                let encoders = self.tools.as_ref().map(|tools| tools.encoders.clone()).unwrap_or_default();
                for (index, format) in FORMATS.iter().enumerate() {
                    let usable = format_available(format, &encoders);
                    let name = if usable { format.label.to_string() } else { format!("{} (not in your FFmpeg)", format.label) };
                    let selected = self.format == FormatChoice::Listed(index);
                    if ui.add_enabled(usable, egui::Button::selectable(selected, name)).clicked() {
                        self.format = FormatChoice::Listed(index);
                        ui.close();
                    }
                }
                let other = matches!(self.format, FormatChoice::Other(_));
                if ui.add(egui::Button::selectable(other, "Other format...")).clicked() {
                    self.format = FormatChoice::Other(self.other_format.clone());
                    ui.close();
                }
            });
            if matches!(self.format, FormatChoice::Other(_)) {
                ui.horizontal(|ui| {
                    ui.label(RichText::new("File type").color(MUTED));
                    let edit = egui::TextEdit::singleline(&mut self.other_format).hint_text("e.g. ogv").desired_width(ui.available_width());
                    if ui.add(edit).changed() {
                        self.format = FormatChoice::Other(self.other_format.clone());
                    }
                });
            }
        });
    }

    fn size_card(&mut self, ui: &mut Ui, plan: Option<&Plan>) {
        card(ui, |ui| {
            section_label(ui, "Final video size");
            let shown = match plan {
                Some(plan) if self.size_preset == 0 && !self.clips.is_empty() => format!("Same as my videos  ({} x {})", plan.width, plan.height),
                _ => SIZE_PRESETS[self.size_preset].0.to_string(),
            };
            egui::ComboBox::from_id_salt("frame").selected_text(shown).width(ui.available_width()).show_ui(ui, |ui| {
                for (index, (name, _)) in SIZE_PRESETS.iter().enumerate() {
                    if ui.add(egui::Button::selectable(self.size_preset == index, *name)).clicked() {
                        self.size_preset = index;
                        ui.close();
                    }
                }
            });
            if self.size_preset + 1 == SIZE_PRESETS.len() {
                ui.horizontal(|ui| {
                    ui.add(egui::TextEdit::singleline(&mut self.custom_width).desired_width(64.0).hint_text("Width"));
                    ui.label(RichText::new("x").color(MUTED));
                    ui.add(egui::TextEdit::singleline(&mut self.custom_height).desired_width(64.0).hint_text("Height"));
                    ui.label(RichText::new("pixels").color(MUTED));
                });
            }
            ui.add_space(2.0);
            ui.horizontal(|ui| {
                ui.style_mut().spacing.item_spacing.x = 4.0;
                let width = (ui.available_width() - 8.0) / 3.0;
                for (fit, name, tip) in [
                    (Fit::Bars, "Fit", "Show the whole picture, with black bars if the shape differs"),
                    (Fit::Crop, "Fill", "Fill the frame, cropping the edges"),
                    (Fit::Stretch, "Stretch", "Fill the frame by stretching the picture"),
                ] {
                    let selected = self.fit == fit;
                    let text = RichText::new(name).size(12.5).color(if selected { Color32::WHITE } else { MUTED });
                    let button = egui::Button::new(text)
                        .fill(if selected { ACCENT.linear_multiply(0.75) } else { RAISED })
                        .stroke(Stroke::new(1.0, if selected { ACCENT } else { LINE }))
                        .min_size(vec2(width, 28.0));
                    if ui.add(button).on_hover_text(tip).clicked() {
                        self.fit = fit;
                    }
                }
            });
        });
    }

    fn parts_card(&mut self, ui: &mut Ui, plan: Option<&Plan>, exporting: bool) {
        card(ui, |ui| {
            ui.add_enabled_ui(!exporting && self.part_states.is_empty(), |ui| {
                ui.horizontal(|ui| {
                    section_label(ui, "Number of videos");
                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                        ui.style_mut().spacing.item_spacing.x = 4.0;
                        let mut count = self.part_limits.len();
                        if ui.add_sized(vec2(28.0, 26.0), egui::Button::new("+")).clicked() && count < 99 {
                            count += 1;
                        }
                        ui.add_sized(vec2(40.0, 26.0), egui::DragValue::new(&mut count).range(1..=99).speed(0.1));
                        if ui.add_sized(vec2(28.0, 26.0), egui::Button::new("-")).clicked() && count > 1 {
                            count -= 1;
                        }
                        self.set_part_count(count);
                    });
                });
                let each = plan.and_then(|plan| plan.parts.first()).map_or(0.0, |part| part.duration);
                if self.part_limits.len() > 1 && each > 0.0 {
                    ui.label(RichText::new(format!("Cut into {} equal parts of {} each, same quality.", self.part_limits.len(), clock(each))).size(12.0).color(MUTED));
                }
                ui.add_space(2.0);
                ui.horizontal(|ui| {
                    section_label(ui, "Max file size");
                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                        let flipped = toggle(ui, &mut self.same_limit);
                        ui.label(RichText::new("Same for all").size(12.0).color(MUTED));
                        if flipped && self.same_limit {
                            let first = self.part_limits[0].clone();
                            self.part_limits.iter_mut().for_each(|limit| *limit = first.clone());
                        }
                    });
                });
            });

            for index in 0..self.part_limits.len() {
                self.part_row(ui, index, plan);
            }
            if !exporting && self.part_states.is_empty() {
                ui.label(RichText::new("Clear a size for no limit, at the best quality.").size(11.5).color(FAINT));
                if self.limits_differ() {
                    ui.label(RichText::new("Different sizes will make the quality differ between parts.").size(11.5).color(WARN));
                }
            }
        });
    }

    fn part_row(&mut self, ui: &mut Ui, index: usize, plan: Option<&Plan>) {
        let part = plan.and_then(|plan| plan.parts.get(index));
        ui.horizontal(|ui| {
            ui.set_height(28.0);
            let (dot, _) = ui.allocate_exact_size(vec2(8.0, 8.0), egui::Sense::hover());
            ui.painter().circle_filled(dot.center(), 4.0, part_color(index));
            let title = if self.part_limits.len() == 1 { "Video".to_string() } else { format!("Part {}", index + 1) };
            ui.label(RichText::new(title).size(13.0));
            if let Some(part) = part {
                ui.label(RichText::new(clock(part.duration)).size(12.0).color(FAINT));
            }
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                match self.part_states.get(index).cloned() {
                    Some(PartState::Waiting) => {
                        ui.label(RichText::new("Waiting").size(12.0).color(FAINT));
                    }
                    Some(PartState::Working { label, fraction }) => {
                        ui.label(RichText::new(label).size(12.0).color(MUTED));
                        ui.add(egui::ProgressBar::new(fraction).desired_width(ui.available_width().max(40.0)).desired_height(8.0));
                    }
                    Some(PartState::Done { bytes, over_limit, .. }) => {
                        let color = if over_limit { WARN } else { GOOD };
                        let text = if over_limit { format!("{} (over)", human_bytes(bytes as f64)) } else { human_bytes(bytes as f64) };
                        ui.label(RichText::new(text).size(12.5).color(color).strong());
                    }
                    Some(PartState::Failed(message)) => {
                        ui.label(RichText::new("Failed").size(12.5).color(BAD)).on_hover_text(message);
                    }
                    None => {
                        if let Some(part) = part {
                            if !self.clips.is_empty() {
                                quality_chip(ui, part.quality, part.video_kbps);
                            }
                        }
                        ui.label(RichText::new("MB").size(12.0).color(MUTED));
                        let valid = self.parse_limit(index).is_ok();
                        let mut edit = egui::TextEdit::singleline(&mut self.part_limits[index])
                            .desired_width(52.0)
                            .horizontal_align(egui::Align::Max)
                            .hint_text("none");
                        if !valid {
                            edit = edit.text_color(BAD);
                        }
                        if ui.add(edit).changed() && self.same_limit {
                            let value = self.part_limits[index].clone();
                            self.part_limits.iter_mut().for_each(|limit| *limit = value.clone());
                        }
                    }
                }
            });
        });
    }

    fn save_card(&mut self, ui: &mut Ui, plan: Option<&Plan>) {
        card(ui, |ui| {
            section_label(ui, "Save to");
            ui.horizontal(|ui| {
                ui.label(RichText::new("Name").color(MUTED));
                let edit = egui::TextEdit::singleline(&mut self.base_name).desired_width(ui.available_width() - 48.0);
                if ui.add(edit).changed() {
                    self.name_edited = true;
                }
                let ext = plan.map_or("mp4".to_string(), |plan| plan.ext.clone());
                ui.label(RichText::new(format!(".{ext}")).color(MUTED));
            });
            ui.horizontal(|ui| {
                let shown = match &self.out_dir {
                    Some(dir) => dir.display().to_string(),
                    None => "Same folder as my videos".to_string(),
                };
                let width = ui.available_width() - 78.0;
                ui.add_sized(vec2(width, 26.0), egui::Label::new(RichText::new(shown).size(12.0).color(MUTED)).truncate());
                if soft_button(ui, "Change").clicked() {
                    self.pick_out_dir();
                }
            });
        });
    }

    fn export_footer(&mut self, ui: &mut Ui, plan: Option<&Plan>) {
        let width = ui.available_width();
        let count = self.part_limits.len();
        if self.exporting() {
            let fraction = self.overall_fraction();
            ui.add(egui::ProgressBar::new(fraction).desired_width(width).desired_height(10.0));
            ui.horizontal(|ui| {
                ui.label(RichText::new(format!("{:.0}%", fraction * 100.0)).strong());
                if let Some(eta) = self.export_eta() {
                    ui.label(RichText::new(format!("about {} left", clock(eta))).size(12.5).color(MUTED));
                }
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if soft_button(ui, "Cancel").clicked() {
                        self.cancel_export();
                    }
                });
            });
            return;
        }
        if let Some(result) = self.export_result.clone() {
            ui.label(RichText::new(result.title.as_str()).color(if result.ok { GOOD } else { WARN }).strong());
            ui.horizontal(|ui| {
                if result.folder.is_some() && soft_button(ui, "Open folder").clicked() {
                    if let Some(folder) = &result.folder {
                        open_folder(folder);
                    }
                }
                if soft_button(ui, "New export").clicked() {
                    self.clear_results();
                }
            });
            return;
        }
        let problem = plan.and_then(|plan| plan.problem.clone()).or_else(|| self.input_problem());
        let label = if count == 1 { "Export video".to_string() } else { format!("Export {count} videos") };
        let ready = self.tools.is_some() && plan.is_some() && problem.is_none();
        let button = primary_button(ui, &label, vec2(width, 46.0), ready);
        if let (true, Some(plan)) = (button.clicked(), plan) {
            self.start_export(plan.clone());
        }
        if let Some(problem) = problem {
            ui.label(RichText::new(problem).size(12.0).color(if self.clips.is_empty() { FAINT } else { WARN }));
        } else if let Some(plan) = plan {
            let budget: Option<u64> = plan.parts.iter().map(|part| part.limit_bytes).sum();
            let hint = match budget {
                Some(bytes) => format!("{} x {} · up to {} in total", plan.width, plan.height, human_bytes(bytes as f64)),
                None => format!("{} x {}", plan.width, plan.height),
            };
            ui.label(RichText::new(hint).size(12.0).color(FAINT));
        }
    }
}

fn quality_chip(ui: &mut Ui, quality: Quality, video_kbps: Option<f64>) {
    let color = match quality {
        Quality::Best | Quality::Great => GOOD,
        Quality::Good => Color32::from_rgb(150, 210, 120),
        Quality::Fair => WARN,
        Quality::Low | Quality::TooSmall => BAD,
    };
    let tip = match video_kbps {
        Some(kbps) if kbps > 0.0 => format!("Estimated quality. The video gets about {:.1} Mbps.", kbps / 1000.0),
        _ => "Estimated quality.".to_string(),
    };
    let text = RichText::new(quality.label()).size(11.5).color(color);
    ui.add_sized(vec2(46.0, 20.0), egui::Label::new(text)).on_hover_text(tip);
}

//! The application's state and everything that changes it. The drawing is in `ui/`.

use crate::ui::theme;
use cutline::export::{self, Event, ExportJob};
use cutline::log::{LogKind, LogLine};
use cutline::media::{self, natural_cmp, MediaInfo, THUMB_HEIGHT, THUMB_WIDTH};
use cutline::plan::{self, Fit, FormatChoice, Plan, Settings};
use cutline::preview::{Preview, PreviewShape, TimelineClip, Update};
use cutline::tools::{self, quiet_command, Tools};
use eframe::egui::{self, Color32, ColorImage, CornerRadius, Margin, RichText, TextureHandle, TextureOptions};
use std::path::{Path, PathBuf};
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::Arc;
use std::time::{Duration, Instant};

const THUMBS_PER_CLIP: usize = 5;
const MAX_CONSOLE_LINES: usize = 5000;
const SCREENSHOT_FRAMES: u64 = 120;
const SCREENSHOT_MAX_FRAMES: u64 = 900;
const VIDEO_EXTENSIONS: &[&str] = &[
    "mp4", "mov", "m4v", "mkv", "webm", "avi", "wmv", "flv", "mpg", "mpeg", "ts", "mts", "m2ts", "3gp", "ogv", "gif", "vob",
];

pub const SIZE_PRESETS: &[(&str, Option<(u32, u32)>)] = &[
    ("Same as my videos", None),
    ("4K  (3840 x 2160)", Some((3840, 2160))),
    ("1440p  (2560 x 1440)", Some((2560, 1440))),
    ("1080p  (1920 x 1080)", Some((1920, 1080))),
    ("720p  (1280 x 720)", Some((1280, 720))),
    ("480p  (854 x 480)", Some((854, 480))),
    ("360p  (640 x 360)", Some((640, 360))),
    ("Vertical  (1080 x 1920)", Some((1080, 1920))),
    ("Square  (1080 x 1080)", Some((1080, 1080))),
    ("Custom size...", None),
];

pub struct ClipItem {
    pub id: u64,
    pub info: MediaInfo,
    pub thumbs: Vec<Option<TextureHandle>>,
}

#[derive(Clone)]
pub enum PartState {
    Waiting,
    Working { label: String, fraction: f32 },
    Done { path: PathBuf, bytes: u64, over_limit: bool },
    Failed(String),
}

#[derive(Clone)]
pub struct ExportResult {
    pub ok: bool,
    pub title: String,
    pub folder: Option<PathBuf>,
}

enum ProbeEvent {
    Log(LogLine),
    Ready { id: u64, info: Box<MediaInfo> },
    Thumb { id: u64, slot: usize, rgba: Vec<u8> },
    Failed(String),
}

struct Toast {
    text: String,
    shown: Instant,
}

/// What `--screenshot` is waiting for.
struct ScreenshotJob {
    path: PathBuf,
    frames: u64,
    requested: bool,
    saved: Receiver<Result<(), String>>,
    saved_tx: Sender<Result<(), String>>,
}

pub struct App {
    ctx: egui::Context,
    pub tools: Option<Tools>,
    saved_ffmpeg: Option<PathBuf>,

    pub clips: Vec<ClipItem>,
    pub manual_order: bool,
    pub selected: Option<u64>,
    pub list_drag: Option<usize>,
    pub timeline_drag: Option<usize>,
    pub probing: usize,
    next_id: u64,
    probe_tx: Option<Sender<(u64, PathBuf)>>,
    probe_rx: Option<Receiver<ProbeEvent>>,

    pub format: FormatChoice,
    pub other_format: String,
    pub size_preset: usize,
    pub custom_width: String,
    pub custom_height: String,
    pub fit: Fit,
    pub part_limits: Vec<String>,
    pub same_limit: bool,
    pub base_name: String,
    pub name_edited: bool,
    pub out_dir: Option<PathBuf>,

    pub playhead: f64,
    pub playing: bool,
    preview: Option<Preview>,
    pub preview_texture: Option<TextureHandle>,
    preview_dirty: bool,
    last_shape: Option<(u32, u32, Fit)>,

    job: Option<ExportJob>,
    pub part_states: Vec<PartState>,
    pub export_result: Option<ExportResult>,
    export_started: Option<Instant>,

    pub console: Vec<LogLine>,
    pub show_console: bool,
    toasts: Vec<Toast>,
    screenshot: Option<ScreenshotJob>,
}

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>, files: Vec<PathBuf>, screenshot: Option<PathBuf>) -> Self {
        theme::apply(&cc.egui_ctx);
        let keep_settings = screenshot.is_none();
        let read = |key: &str| cc.storage.filter(|_| keep_settings).and_then(|storage| storage.get_string(key)).filter(|text| !text.is_empty());
        let (saved_tx, saved) = channel();
        let mut app = Self {
            ctx: cc.egui_ctx.clone(),
            tools: None,
            saved_ffmpeg: read("ffmpeg").map(PathBuf::from),
            clips: Vec::new(),
            manual_order: false,
            selected: None,
            list_drag: None,
            timeline_drag: None,
            probing: 0,
            next_id: 1,
            probe_tx: None,
            probe_rx: None,
            format: FormatChoice::Listed(0),
            other_format: String::new(),
            size_preset: 0,
            custom_width: "1280".to_string(),
            custom_height: "720".to_string(),
            fit: Fit::Bars,
            part_limits: vec!["20".to_string()],
            same_limit: true,
            base_name: "edited_video".to_string(),
            name_edited: false,
            out_dir: read("out_dir").map(PathBuf::from),
            playhead: 0.0,
            playing: false,
            preview: None,
            preview_texture: None,
            preview_dirty: false,
            last_shape: None,
            job: None,
            part_states: Vec::new(),
            export_result: None,
            export_started: None,
            console: Vec::new(),
            show_console: read("show_console").as_deref() == Some("1"),
            toasts: Vec::new(),
            screenshot: screenshot.map(|path| ScreenshotJob { path, frames: 0, requested: false, saved, saved_tx }),
        };
        app.find_tools();
        app.add_files(files);
        app
    }

    fn wake(&self) -> Arc<dyn Fn() + Send + Sync> {
        let ctx = self.ctx.clone();
        Arc::new(move || ctx.request_repaint())
    }

    /// Look for FFmpeg and start the background helpers when it's there.
    pub fn find_tools(&mut self) {
        self.tools = tools::locate(self.saved_ffmpeg.as_deref());
        let Some(tools) = self.tools.clone() else {
            self.preview = None;
            self.probe_tx = None;
            self.probe_rx = None;
            return;
        };
        self.log(LogKind::Info, format!("Using {}", tools.version));
        self.preview = Some(Preview::new(tools.clone(), self.wake()));
        let (job_tx, job_rx) = channel();
        let (event_tx, event_rx) = channel();
        let wake = self.wake();
        std::thread::spawn(move || probe_worker(tools, job_rx, event_tx, wake));
        self.probe_tx = Some(job_tx);
        self.probe_rx = Some(event_rx);
    }

    pub fn pick_ffmpeg(&mut self) {
        if let Some(path) = rfd::FileDialog::new().set_title("Find your FFmpeg program").pick_file() {
            self.saved_ffmpeg = Some(path);
            self.find_tools();
            if self.tools.is_none() {
                self.toast("That file doesn't look like FFmpeg");
            }
        }
    }

    pub fn add_with_dialog(&mut self) {
        let picked = rfd::FileDialog::new().set_title("Add videos").add_filter("Videos", VIDEO_EXTENSIONS).add_filter("All files", &["*"]).pick_files();
        if let Some(files) = picked {
            self.add_files(files);
        }
    }

    pub fn pick_out_dir(&mut self) {
        if let Some(dir) = rfd::FileDialog::new().set_title("Where should the videos go?").pick_folder() {
            self.out_dir = Some(dir);
        }
    }

    /// Queue files (or the videos in dropped folders) for reading.
    pub fn add_files(&mut self, files: Vec<PathBuf>) {
        let Some(sender) = self.probe_tx.clone() else {
            if !files.is_empty() {
                self.toast("Cutline needs FFmpeg before it can read videos");
            }
            return;
        };
        let mut paths = Vec::new();
        for path in files {
            if path.is_dir() {
                let mut inside: Vec<PathBuf> = std::fs::read_dir(&path)
                    .map(|entries| entries.flatten().map(|entry| entry.path()).filter(|file| is_video_name(file)).collect())
                    .unwrap_or_default();
                inside.sort_by(|a, b| natural_cmp(&a.to_string_lossy(), &b.to_string_lossy()));
                paths.extend(inside);
            } else {
                paths.push(path);
            }
        }
        for path in paths {
            let id = self.next_id;
            self.next_id += 1;
            self.probing += 1;
            let _ = sender.send((id, path));
        }
    }

    pub fn total_duration(&self) -> f64 {
        self.clips.iter().map(|clip| clip.info.duration).sum()
    }

    fn clip_start(&self, index: usize) -> f64 {
        self.clips[..index].iter().map(|clip| clip.info.duration).sum()
    }

    fn after_clip_change(&mut self) {
        self.stop_playing();
        self.playhead = self.playhead.min(self.total_duration());
        self.preview_dirty = true;
        self.clear_results();
    }

    pub fn move_clip(&mut self, from: usize, target: usize) {
        if from >= self.clips.len() || target > self.clips.len() {
            return;
        }
        let clip = self.clips.remove(from);
        let insert_at = if target > from { target - 1 } else { target };
        self.clips.insert(insert_at, clip);
        self.manual_order = true;
        self.after_clip_change();
    }

    pub fn remove_clip(&mut self, index: usize) {
        if index < self.clips.len() {
            self.clips.remove(index);
            if self.clips.is_empty() {
                self.preview_texture = None;
                self.manual_order = false;
            }
            self.after_clip_change();
        }
    }

    pub fn sort_alphabetically(&mut self) {
        self.clips.sort_by(|a, b| natural_cmp(&a.info.name, &b.info.name));
        self.manual_order = false;
        self.after_clip_change();
    }

    pub fn select_clip(&mut self, index: usize) {
        self.selected = self.clips.get(index).map(|clip| clip.id);
        let start = self.clip_start(index);
        self.seek(start);
    }

    pub fn seek(&mut self, at: f64) {
        self.stop_playing();
        let total = self.total_duration();
        self.playhead = at.clamp(0.0, (total - 0.05).max(0.0));
        self.preview_dirty = true;
    }

    pub fn skip_clip(&mut self, forward: bool) {
        let mut start = 0.0;
        let mut starts = Vec::with_capacity(self.clips.len());
        for clip in &self.clips {
            starts.push(start);
            start += clip.info.duration;
        }
        let target = if forward {
            starts.iter().copied().find(|time| *time > self.playhead + 0.01)
        } else {
            starts.iter().copied().rev().find(|time| *time < self.playhead - 0.5).or(Some(0.0))
        };
        if let Some(target) = target {
            self.seek(target);
        }
    }

    fn timeline_clips(&self) -> Arc<Vec<TimelineClip>> {
        let mut start = 0.0;
        let clips = self
            .clips
            .iter()
            .map(|clip| {
                let item = TimelineClip { path: clip.info.path.clone(), start, duration: clip.info.duration };
                start += clip.info.duration;
                item
            })
            .collect();
        Arc::new(clips)
    }

    fn preview_shape(&self) -> PreviewShape {
        let (width, height) = self.output_dims();
        PreviewShape::for_output(width, height, self.fit)
    }

    pub fn toggle_play(&mut self) {
        if self.playing {
            self.stop_playing();
            self.preview_dirty = true;
        } else if !self.clips.is_empty() {
            if self.playhead >= self.total_duration() - 0.1 {
                self.playhead = 0.0;
            }
            if let Some(preview) = &self.preview {
                preview.play(self.timeline_clips(), self.playhead, self.preview_shape());
                self.playing = true;
            }
        }
    }

    fn stop_playing(&mut self) {
        if self.playing {
            self.playing = false;
            if let Some(preview) = &self.preview {
                preview.stop();
            }
        }
    }

    pub fn exporting(&self) -> bool {
        self.job.is_some()
    }

    pub fn set_part_count(&mut self, count: usize) {
        if count == self.part_limits.len() || count == 0 {
            return;
        }
        let last = self.part_limits.last().cloned().unwrap_or_else(|| "20".to_string());
        self.part_limits.resize(count, last);
    }

    /// A size field: `Ok(None)` when empty (no limit), `Err` when it isn't a usable number.
    pub fn parse_limit(&self, index: usize) -> Result<Option<f64>, ()> {
        let text = self.part_limits[index].trim().replace(',', ".");
        if text.is_empty() {
            return Ok(None);
        }
        match text.parse::<f64>() {
            Ok(value) if value > 0.0 && value.is_finite() => Ok(Some(value)),
            _ => Err(()),
        }
    }

    pub fn limits_differ(&self) -> bool {
        let first = self.part_limits.first();
        !self.same_limit && self.part_limits.iter().any(|limit| Some(limit) != first)
    }

    fn custom_frame(&self) -> Option<(u32, u32)> {
        let width = self.custom_width.trim().parse::<u32>().ok().filter(|v| (16..=8192).contains(v))?;
        let height = self.custom_height.trim().parse::<u32>().ok().filter(|v| (16..=8192).contains(v))?;
        Some((width, height))
    }

    fn chosen_frame(&self) -> Option<(u32, u32)> {
        if self.size_preset + 1 == SIZE_PRESETS.len() {
            self.custom_frame()
        } else {
            SIZE_PRESETS[self.size_preset].1
        }
    }

    pub fn output_dims(&self) -> (u32, u32) {
        let infos: Vec<MediaInfo> = self.clips.iter().map(|clip| clip.info.clone()).collect();
        self.chosen_frame().unwrap_or_else(|| plan::source_frame(&infos))
    }

    /// What's wrong with the typed-in settings, in words.
    pub fn input_problem(&self) -> Option<String> {
        if self.size_preset + 1 == SIZE_PRESETS.len() && self.custom_frame().is_none() {
            return Some("Enter a width and height between 16 and 8192.".to_string());
        }
        (0..self.part_limits.len())
            .find(|index| self.parse_limit(*index).is_err())
            .map(|index| format!("Part {}'s size isn't a number.", index + 1))
    }

    fn effective_out_dir(&self) -> PathBuf {
        if let Some(dir) = &self.out_dir {
            return dir.clone();
        }
        self.clips
            .first()
            .and_then(|clip| clip.info.path.parent().map(Path::to_path_buf))
            .or_else(|| std::env::var_os(if cfg!(windows) { "USERPROFILE" } else { "HOME" }).map(PathBuf::from))
            .unwrap_or_else(std::env::temp_dir)
    }

    fn current_plan(&self) -> Plan {
        let infos: Vec<MediaInfo> = self.clips.iter().map(|clip| clip.info.clone()).collect();
        let settings = Settings {
            format: self.format.clone(),
            frame: self.chosen_frame(),
            fit: self.fit,
            limits_mb: (0..self.part_limits.len()).map(|index| self.parse_limit(index).unwrap_or(None)).collect(),
            out_dir: self.effective_out_dir(),
            base_name: self.base_name.trim().to_string(),
        };
        let encoders = self.tools.as_ref().map(|tools| tools.encoders.clone()).unwrap_or_default();
        plan::build(&infos, &settings, &encoders, &|path| path.exists())
    }

    pub fn start_export(&mut self, plan: Plan) {
        let Some(tools) = self.tools.clone() else { return };
        self.stop_playing();
        self.part_states = plan.parts.iter().map(|_| PartState::Waiting).collect();
        self.export_result = None;
        self.export_started = Some(Instant::now());
        self.job = Some(export::start(plan, tools, self.wake()));
    }

    pub fn cancel_export(&mut self) {
        if let Some(job) = &self.job {
            job.cancel();
        }
    }

    pub fn clear_results(&mut self) {
        if self.job.is_none() {
            self.part_states.clear();
            self.export_result = None;
        }
    }

    pub fn overall_fraction(&self) -> f32 {
        if self.part_states.is_empty() {
            return 0.0;
        }
        let sum: f32 = self
            .part_states
            .iter()
            .map(|state| match state {
                PartState::Done { .. } | PartState::Failed(_) => 1.0,
                PartState::Working { fraction, .. } => *fraction,
                PartState::Waiting => 0.0,
            })
            .sum();
        sum / self.part_states.len() as f32
    }

    pub fn export_eta(&self) -> Option<f64> {
        let started = self.export_started?;
        export::eta(started, self.overall_fraction()).map(|left| left.as_secs_f64())
    }

    pub fn log(&mut self, kind: LogKind, text: impl Into<String>) {
        self.push_log(LogLine::new(kind, text));
    }

    fn push_log(&mut self, line: LogLine) {
        if line.kind == LogKind::Live && self.console.last().is_some_and(|last| last.kind == LogKind::Live) {
            self.console.pop();
        }
        self.console.push(line);
        if self.console.len() > MAX_CONSOLE_LINES {
            let extra = self.console.len() - MAX_CONSOLE_LINES;
            self.console.drain(..extra);
        }
    }

    pub fn toast(&mut self, text: impl Into<String>) {
        self.toasts.push(Toast { text: text.into(), shown: Instant::now() });
    }

    fn poll_probes(&mut self, ctx: &egui::Context) {
        let events: Vec<ProbeEvent> = self.probe_rx.as_ref().map_or(Vec::new(), |rx| rx.try_iter().collect());
        for event in events {
            match event {
                ProbeEvent::Log(line) => self.push_log(line),
                ProbeEvent::Ready { id, info } => {
                    self.probing = self.probing.saturating_sub(1);
                    self.clips.push(ClipItem { id, info: *info, thumbs: vec![None; THUMBS_PER_CLIP] });
                    if !self.manual_order {
                        self.clips.sort_by(|a, b| natural_cmp(&a.info.name, &b.info.name));
                    }
                    if !self.name_edited {
                        if let Some(first) = self.clips.first() {
                            let stem = Path::new(&first.info.name).file_stem().unwrap_or_default().to_string_lossy();
                            self.base_name = format!("{stem}_edited");
                        }
                    }
                    self.after_clip_change();
                }
                ProbeEvent::Thumb { id, slot, rgba } => {
                    if let Some(clip) = self.clips.iter_mut().find(|clip| clip.id == id) {
                        let image = ColorImage::from_rgba_unmultiplied([THUMB_WIDTH as usize, THUMB_HEIGHT as usize], &rgba);
                        clip.thumbs[slot] = Some(ctx.load_texture(format!("thumb-{id}-{slot}"), image, TextureOptions::LINEAR));
                    }
                }
                ProbeEvent::Failed(message) => {
                    self.probing = self.probing.saturating_sub(1);
                    self.log(LogKind::Warning, message.clone());
                    self.toast(message);
                }
            }
        }
    }

    fn poll_preview(&mut self, ctx: &egui::Context) {
        let updates: Vec<Update> = self.preview.as_ref().map_or(Vec::new(), |preview| preview.updates.try_iter().collect());
        for update in updates {
            match update {
                Update::Frame(frame) => {
                    if self.playing {
                        self.playhead = frame.at;
                    }
                    let image = ColorImage::from_rgba_unmultiplied([frame.width, frame.height], &frame.rgba);
                    match &mut self.preview_texture {
                        Some(texture) => texture.set(image, TextureOptions::LINEAR),
                        None => self.preview_texture = Some(ctx.load_texture("preview", image, TextureOptions::LINEAR)),
                    }
                }
                Update::Ended => {
                    self.playing = false;
                    self.preview_dirty = true;
                }
            }
        }
    }

    fn poll_export(&mut self) {
        let events: Vec<Event> = self.job.as_ref().map_or(Vec::new(), |job| job.events.try_iter().collect());
        for event in events {
            match event {
                Event::Log(line) => self.push_log(line),
                Event::Stage { part, label } => {
                    let fraction = match &self.part_states[part] {
                        PartState::Working { fraction, .. } => *fraction,
                        _ => 0.0,
                    };
                    self.part_states[part] = PartState::Working { label, fraction };
                }
                Event::Progress { part, fraction, .. } => {
                    if let PartState::Working { label, .. } = &self.part_states[part] {
                        self.part_states[part] = PartState::Working { label: label.clone(), fraction };
                    }
                }
                Event::PartDone { part, path, bytes, over_limit } => {
                    self.part_states[part] = PartState::Done { path, bytes, over_limit };
                }
                Event::PartFailed { part, message } => {
                    self.part_states[part] = PartState::Failed(message);
                }
                Event::Finished { cancelled } => self.finish_export(cancelled),
            }
        }
    }

    fn finish_export(&mut self, cancelled: bool) {
        self.job = None;
        let total = self.part_states.len();
        let done = self.part_states.iter().filter(|state| matches!(state, PartState::Done { .. })).count();
        let over = self.part_states.iter().filter(|state| matches!(state, PartState::Done { over_limit: true, .. })).count();
        let failed = self.part_states.iter().filter(|state| matches!(state, PartState::Failed(_))).count();
        let folder = self
            .part_states
            .iter()
            .find_map(|state| match state {
                PartState::Done { path, .. } => path.parent().map(Path::to_path_buf),
                _ => None,
            });
        let (ok, title) = if cancelled {
            (false, format!("Stopped. {done} of {total} finished."))
        } else if failed > 0 {
            (false, format!("{failed} of {total} failed. The console has the details."))
        } else if over > 0 {
            (false, format!("Saved, but {over} went over its size limit."))
        } else if total == 1 {
            (true, "Your video is saved".to_string())
        } else {
            (true, format!("All {total} videos are saved"))
        };
        self.export_result = Some(ExportResult { ok, title, folder });
        if !cancelled && failed > 0 {
            self.show_console = true;
        }
    }

    fn refresh_preview(&mut self) {
        if self.clips.is_empty() {
            return;
        }
        let (width, height) = self.output_dims();
        let shape = (width, height, self.fit);
        if self.last_shape != Some(shape) {
            self.last_shape = Some(shape);
            self.preview_dirty = true;
        }
        if self.preview_dirty && !self.playing {
            if let Some(preview) = &self.preview {
                preview.show(self.timeline_clips(), self.playhead, self.preview_shape());
            }
            self.preview_dirty = false;
        }
    }

    fn handle_shortcuts(&mut self, ctx: &egui::Context) {
        let typing = ctx.memory(|memory| memory.focused().is_some());
        if !typing && ctx.input(|input| input.key_pressed(egui::Key::Space)) {
            self.toggle_play();
        }
        if !typing && !self.exporting() && ctx.input(|input| input.key_pressed(egui::Key::Delete)) {
            if let Some(index) = self.clips.iter().position(|clip| Some(clip.id) == self.selected) {
                self.remove_clip(index);
            }
        }
        let dropped: Vec<PathBuf> = ctx.input(|input| input.raw.dropped_files.iter().filter_map(|file| file.path.clone()).collect());
        if !dropped.is_empty() && !self.exporting() {
            self.add_files(dropped);
        }
    }

    fn top_bar(&mut self, ui: &mut egui::Ui) {
        ui.horizontal_centered(|ui| {
            let (mark, _) = ui.allocate_exact_size(egui::vec2(26.0, 26.0), egui::Sense::hover());
            let painter = ui.painter();
            painter.rect_filled(mark, CornerRadius::same(7), theme::ACCENT);
            theme::triangle(painter, mark.center() + egui::vec2(1.0, 0.0), 6.5, 1.0, Color32::WHITE);
            ui.label(RichText::new("Cutline").size(17.0).strong());
            if !self.clips.is_empty() {
                let count = self.clips.len();
                let noun = if count == 1 { "video" } else { "videos" };
                ui.add_space(10.0);
                ui.label(RichText::new(format!("{count} {noun} · {} in total", media::clock(self.total_duration()))).size(12.5).color(theme::MUTED));
            }
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                theme::toggle(ui, &mut self.show_console);
                ui.label(RichText::new("View console").size(13.0));
                if self.exporting() && !self.show_console {
                    ui.spinner();
                }
            });
        });
    }

    fn drop_overlay(&self, ctx: &egui::Context) {
        if ctx.input(|input| input.raw.hovered_files.is_empty()) {
            return;
        }
        let painter = ctx.layer_painter(egui::LayerId::new(egui::Order::Foreground, egui::Id::new("drop overlay")));
        let screen = ctx.content_rect();
        painter.rect_filled(screen, CornerRadius::ZERO, Color32::from_rgba_unmultiplied(15, 17, 21, 225));
        theme::dashed_rect(&painter, screen.shrink(18.0), egui::Stroke::new(3.0, theme::ACCENT_HOVER));
        painter.text(screen.center() - egui::vec2(0.0, 12.0), egui::Align2::CENTER_CENTER, "Drop to add", egui::FontId::proportional(30.0), theme::TEXT);
        painter.text(
            screen.center() + egui::vec2(0.0, 24.0),
            egui::Align2::CENTER_CENTER,
            "They'll be added in alphabetical order",
            egui::FontId::proportional(15.0),
            theme::MUTED,
        );
    }

    fn draw_toasts(&mut self, ctx: &egui::Context) {
        self.toasts.retain(|toast| toast.shown.elapsed() < Duration::from_secs(4));
        if self.toasts.is_empty() {
            return;
        }
        egui::Area::new(egui::Id::new("toasts"))
            .order(egui::Order::Foreground)
            .anchor(egui::Align2::CENTER_BOTTOM, egui::vec2(0.0, -210.0))
            .show(ctx, |ui| {
                for toast in &self.toasts {
                    egui::Frame::new()
                        .fill(theme::RAISED)
                        .stroke(egui::Stroke::new(1.0, theme::LINE))
                        .corner_radius(CornerRadius::same(9))
                        .inner_margin(Margin::symmetric(14, 9))
                        .show(ui, |ui| ui.label(RichText::new(toast.text.as_str()).size(13.0)));
                }
            });
        ctx.request_repaint_after(Duration::from_millis(300));
    }

    fn run_screenshot(&mut self, ctx: &egui::Context) {
        let settled = self.probing == 0
            && self.clips.iter().all(|clip| clip.thumbs.iter().all(Option::is_some))
            && (self.clips.is_empty() || self.preview_texture.is_some());
        let Some(job) = &mut self.screenshot else { return };
        job.frames += 1;
        ctx.request_repaint();
        if !job.requested && job.frames >= SCREENSHOT_FRAMES && (settled || job.frames >= SCREENSHOT_MAX_FRAMES) {
            job.requested = true;
            let (path, done) = (job.path.clone(), job.saved_tx.clone());
            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::ScreenshotCallback::new(move |image| {
                let _ = done.send(save_png(&image, &path));
            })));
        }
        if let Ok(result) = job.saved.try_recv() {
            if let Err(message) = result {
                eprintln!("Couldn't save the screenshot: {message}");
            }
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
    }
}

impl eframe::App for App {
    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        let ctx = ui.ctx().clone();
        self.poll_probes(&ctx);
        self.poll_preview(&ctx);
        self.poll_export();
        self.handle_shortcuts(&ctx);
        let plan = self.current_plan();
        self.refresh_preview();
        if self.exporting() || self.probing > 0 {
            ctx.request_repaint_after(Duration::from_millis(120));
        }

        let panel_frame = |margin: i8| egui::Frame::new().fill(theme::PANEL).inner_margin(Margin::same(margin));
        egui::Panel::top("top bar")
            .frame(egui::Frame::new().fill(theme::PANEL).inner_margin(Margin::symmetric(14, 8)))
            .exact_size(50.0)
            .show_inside(ui, |ui| self.top_bar(ui));
        if self.show_console {
            egui::Panel::bottom("console")
                .frame(panel_frame(10))
                .resizable(true)
                .default_size(220.0)
                .min_size(120.0)
                .max_size(520.0)
                .show_inside(ui, |ui| self.console_panel(ui));
        }
        egui::Panel::bottom("timeline")
            .frame(panel_frame(12))
            .exact_size(176.0)
            .show_inside(ui, |ui| self.timeline_panel(ui, Some(&plan)));
        egui::Panel::left("media")
            .frame(panel_frame(12))
            .resizable(true)
            .default_size(300.0)
            .min_size(240.0)
            .max_size(460.0)
            .show_inside(ui, |ui| self.media_panel(ui));
        egui::Panel::right("output")
            .frame(panel_frame(12))
            .resizable(true)
            .default_size(340.0)
            .min_size(300.0)
            .max_size(460.0)
            .show_inside(ui, |ui| self.output_panel(ui, Some(&plan)));
        egui::CentralPanel::default()
            .frame(egui::Frame::new().fill(theme::BG).inner_margin(Margin::same(12)))
            .show_inside(ui, |ui| self.preview_panel(ui));

        self.drop_overlay(&ctx);
        self.draw_toasts(&ctx);
        self.run_screenshot(&ctx);
    }

    fn save(&mut self, storage: &mut dyn eframe::Storage) {
        if self.screenshot.is_some() {
            return;
        }
        let path_text = |path: &Option<PathBuf>| path.as_ref().map(|path| path.display().to_string()).unwrap_or_default();
        storage.set_string("ffmpeg", path_text(&self.saved_ffmpeg));
        storage.set_string("out_dir", path_text(&self.out_dir));
        storage.set_string("show_console", if self.show_console { "1" } else { "0" }.to_string());
    }

    fn persist_egui_memory(&self) -> bool {
        self.screenshot.is_none()
    }

    fn on_exit(&mut self, _gl: Option<&eframe::glow::Context>) {
        if let Some(job) = &self.job {
            job.cancel();
            let deadline = Instant::now() + Duration::from_secs(3);
            while Instant::now() < deadline {
                match job.events.recv_timeout(Duration::from_millis(200)) {
                    Ok(Event::Finished { .. }) => break,
                    _ => continue,
                }
            }
        }
    }
}

fn is_video_name(path: &Path) -> bool {
    path.extension().is_some_and(|ext| VIDEO_EXTENSIONS.contains(&ext.to_string_lossy().to_lowercase().as_str()))
}

fn probe_worker(tools: Tools, jobs: Receiver<(u64, PathBuf)>, events: Sender<ProbeEvent>, wake: Arc<dyn Fn() + Send + Sync>) {
    for (id, path) in jobs {
        let mut log = |line| {
            let _ = events.send(ProbeEvent::Log(line));
        };
        match media::probe(&tools, &path, &mut log) {
            Err(message) => {
                let _ = events.send(ProbeEvent::Failed(message));
                wake();
            }
            Ok(info) => {
                let duration = info.duration;
                let source = info.path.clone();
                let _ = events.send(ProbeEvent::Ready { id, info: Box::new(info) });
                wake();
                for slot in 0..THUMBS_PER_CLIP {
                    let at = duration * (slot as f64 + 0.5) / THUMBS_PER_CLIP as f64;
                    if let Some(rgba) = media::grab_thumbnail(&tools, &source, at) {
                        let _ = events.send(ProbeEvent::Thumb { id, slot, rgba });
                        wake();
                    }
                }
            }
        }
    }
}

fn save_png(image: &ColorImage, path: &Path) -> Result<(), String> {
    if let Some(parent) = path.parent().filter(|parent| !parent.as_os_str().is_empty()) {
        std::fs::create_dir_all(parent).map_err(|error| error.to_string())?;
    }
    let file = std::fs::File::create(path).map_err(|error| error.to_string())?;
    let [width, height] = image.size;
    let mut encoder = png::Encoder::new(std::io::BufWriter::new(file), width as u32, height as u32);
    encoder.set_color(png::ColorType::Rgba);
    encoder.set_depth(png::BitDepth::Eight);
    let mut writer = encoder.write_header().map_err(|error| error.to_string())?;
    let bytes: Vec<u8> = image.pixels.iter().flat_map(|pixel| [pixel.r(), pixel.g(), pixel.b(), 255]).collect();
    writer.write_image_data(&bytes).map_err(|error| error.to_string())
}

/// Show a folder in the system's file manager.
pub fn open_folder(path: &Path) {
    let program = if cfg!(target_os = "macos") {
        "open"
    } else if cfg!(windows) {
        "explorer"
    } else {
        "xdg-open"
    };
    let _ = quiet_command(std::ffi::OsStr::new(program)).arg(path).spawn();
}

