// Test driver: real X11 drag and drop (XDND source), XTEST mouse/keyboard and x11grab screenshots.
use std::{thread::sleep, time::{Duration, Instant}, process::Command};
use x11rb::{connection::Connection, protocol::{xproto::*, xtest::ConnectionExt as _, Event}, wrapper::ConnectionExt as _, COPY_DEPTH_FROM_PARENT, CURRENT_TIME};

fn atom(c: &impl Connection, name: &str) -> Atom { c.intern_atom(false, name.as_bytes()).unwrap().reply().unwrap().atom }

fn find(c: &impl Connection, root: Window) -> Window {
    for _ in 0..200 {
        for w in c.query_tree(root).unwrap().reply().unwrap().children {
            let n = c.get_property(false, w, AtomEnum::WM_NAME, AtomEnum::ANY, 0, 64).unwrap().reply().unwrap().value;
            if String::from_utf8_lossy(&n).contains("Cutline") { return w; }
        }
        sleep(Duration::from_millis(100));
    }
    panic!("no window")
}

fn drop_files(c: &impl Connection, root: Window, target: Window, files: &[String]) {
    let src = c.generate_id().unwrap();
    c.create_window(COPY_DEPTH_FROM_PARENT, src, root, 0, 0, 1, 1, 0, WindowClass::INPUT_OUTPUT, 0, &CreateWindowAux::new()).unwrap();
    let (sel, enter, pos, status, dropm, fin, uri, copy) = (atom(c, "XdndSelection"), atom(c, "XdndEnter"), atom(c, "XdndPosition"), atom(c, "XdndStatus"), atom(c, "XdndDrop"), atom(c, "XdndFinished"), atom(c, "text/uri-list"), atom(c, "XdndActionCopy"));
    c.set_selection_owner(src, sel, CURRENT_TIME).unwrap();
    let send = |ty: Atom, d: [u32; 5]| {
        let ev = ClientMessageEvent::new(32, target, ty, d);
        c.send_event(false, target, EventMask::NO_EVENT, ev).unwrap();
        c.flush().unwrap();
    };
    send(enter, [src, 5 << 24, uri, 0, 0]);
    send(pos, [src, 0, (500 << 16) | 300, 0, copy]);
    let body: String = files.iter().map(|f| format!("file://{}\r\n", f.replace(' ', "%20"))).collect();
    let start = Instant::now();
    let mut dropped = false;
    while start.elapsed() < Duration::from_secs(10) {
        if let Some(ev) = c.poll_for_event().unwrap() {
            match ev {
                Event::ClientMessage(m) if m.type_ == status && !dropped => { dropped = true; println!("target accepted: {:?}", m.data.as_data32()); send(dropm, [src, 0, 0, 0, 0]); }
                Event::ClientMessage(m) if m.type_ == fin => { println!("XdndFinished"); return; }
                Event::SelectionRequest(r) => {
                    c.change_property8(PropMode::REPLACE, r.requestor, r.property, uri, body.as_bytes()).unwrap();
                    let n = SelectionNotifyEvent { response_type: SELECTION_NOTIFY_EVENT, sequence: 0, time: r.time, requestor: r.requestor, selection: r.selection, target: r.target, property: r.property };
                    c.send_event(false, r.requestor, EventMask::NO_EVENT, n).unwrap();
                    c.flush().unwrap();
                }
                _ => {}
            }
        } else { sleep(Duration::from_millis(10)); }
    }
    println!("drop timed out");
}

fn ffmpeg_running() -> bool {
    std::fs::read_dir("/proc").unwrap().flatten().any(|e| {
        let name = e.file_name().to_string_lossy().to_string();
        name.chars().all(|c| c.is_ascii_digit()) && std::fs::read_to_string(e.path().join("comm")).map_or(false, |c| c.trim() == "ffmpeg")
            && std::fs::read_to_string(e.path().join("environ")).map_or(false, |v| v.contains("DISPLAY=:77"))
    })
}

fn main() {
    let (c, screen) = x11rb::connect(None).unwrap();
    let root = c.setup().roots[screen].root;
    let win = find(&c, root);
    let geo = c.translate_coordinates(win, root, 0, 0).unwrap().reply().unwrap();
    println!("window at {},{}", geo.dst_x, geo.dst_y);
    let mut i = 1;
    let a: Vec<String> = std::env::args().collect();
    let move_to = |x: i16, y: i16| { c.xtest_fake_input(MOTION_NOTIFY_EVENT, 0, 0, root, x + geo.dst_x, y + geo.dst_y, 0).unwrap(); c.flush().unwrap(); sleep(Duration::from_millis(140)); };
    let button = |t: u8| { c.xtest_fake_input(t, 1, 0, root, 0, 0, 0).unwrap(); c.flush().unwrap(); sleep(Duration::from_millis(140)); };
    while i < a.len() {
        match a[i].as_str() {
            "wait" => { sleep(Duration::from_millis(a[i+1].parse().unwrap())); i += 2; }
            "shot" => { let s = Command::new("ffmpeg").args(["-y","-hide_banner","-loglevel","error","-f","x11grab","-video_size","1360x860","-i",":77+0,0","-frames:v","1",&a[i+1]]).status().unwrap(); println!("shot {} {s}", a[i+1]); i += 2; }
            "click" => { let (x, y) = (a[i+1].parse().unwrap(), a[i+2].parse().unwrap()); move_to(x, y); button(BUTTON_PRESS_EVENT); button(BUTTON_RELEASE_EVENT); i += 3; }
            "drag" => {
                let n: Vec<i16> = a[i+1..i+5].iter().map(|v| v.parse().unwrap()).collect();
                move_to(n[0], n[1]); button(BUTTON_PRESS_EVENT);
                for s in 1..=8 { move_to(n[0] + (n[2]-n[0])*s/8, n[1] + (n[3]-n[1])*s/8); }
                button(BUTTON_RELEASE_EVENT); i += 5;
            }
            "focus" => { c.set_input_focus(InputFocus::POINTER_ROOT, win, CURRENT_TIME).unwrap(); c.flush().unwrap(); sleep(Duration::from_millis(300)); i += 1; }
            "key" => { let k: u8 = a[i+1].parse().unwrap(); c.xtest_fake_input(KEY_PRESS_EVENT, k, 0, root, 0, 0, 0).unwrap(); c.xtest_fake_input(KEY_RELEASE_EVENT, k, 0, root, 0, 0, 0).unwrap(); c.flush().unwrap(); sleep(Duration::from_millis(160)); i += 2; }
            "drop" => { let rest: Vec<String> = a[i+1..].iter().take_while(|v| *v != "--").cloned().collect(); drop_files(&c, root, win, &rest); i += rest.len() + 2; }
            "idle" => { let start = Instant::now(); let mut quiet = 0; while start.elapsed() < Duration::from_secs(a[i+1].parse().unwrap()) { if ffmpeg_running() { quiet = 0 } else { quiet += 1; if quiet > 12 { break; } } sleep(Duration::from_millis(250)); } println!("idle after {:?}", start.elapsed()); i += 2; }
            other => panic!("unknown {other}"),
        }
    }
}
